/* === 双平台同步条 === */
.sync-banner {
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  padding: 10px 24px; background: linear-gradient(90deg, #e7f5ff 0%, #e6fcf5 100%);
  border-bottom: 1px solid #b6e3f4; font-size: 13px;
}
.sync-banner .sync-pair {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 12px; background: rgba(255,255,255,0.85);
  border-radius: 20px; border: 1px solid var(--border);
}
.sync-banner .sync-pair .pill-ops { color: var(--primary); font-weight: 600; }
.sync-banner .sync-pair .pill-dev { color: #087f5b; font-weight: 600; }
.sync-banner .sync-meta { color: var(--text-muted); font-size: 12px; }
.sync-banner .sync-actions { margin-left: auto; display: flex; gap: 8px; align-items: center; }

/* === 配置页 Tab === */
.editor-tabs {
  display: flex; gap: 0; padding: 0 24px;
  background: var(--bg-white); border-bottom: 1px solid var(--border);
}
.editor-tabs a, .editor-tabs button {
  padding: 12px 20px; font-size: 14px; color: var(--text-secondary);
  border: none; background: none; border-bottom: 2px solid transparent;
  margin-bottom: -1px; cursor: pointer;
}
.editor-tabs a:hover, .editor-tabs button:hover { color: var(--primary); }
.editor-tabs a.active, .editor-tabs button.active {
  color: var(--primary); font-weight: 600; border-bottom-color: var(--primary);
}
.agent-tab-panel { display: none; }
.agent-tab-panel.active { display: block; }

/* === 资源迷你表（仿开发平台列表） === */
.res-toolbar {
  display: flex; align-items: center; gap: 8px; margin-bottom: 10px; flex-wrap: wrap;
}
.res-toolbar .input { flex: 1; min-width: 120px; max-width: 200px; padding: 6px 10px; font-size: 12px; }
.res-mini-table { width: 100%; border-collapse: collapse; font-size: 12px; border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.res-mini-table th {
  text-align: left; padding: 8px 10px; background: #fafbfc;
  color: var(--text-muted); font-weight: 500; border-bottom: 1px solid var(--border);
}
.res-mini-table td { padding: 10px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.res-mini-table tr:last-child td { border-bottom: none; }
.res-mini-table tr:hover td { background: var(--bg-hover); }
.res-link { color: var(--primary); font-size: 12px; cursor: pointer; }
.res-link:hover { text-decoration: underline; }

/* === 开发平台侧栏布局 === */
.dev-layout { display: flex; min-height: calc(100vh - var(--topnav-h)); }
.dev-side {
  width: 220px; flex-shrink: 0; background: var(--bg-white);
  border-right: 1px solid var(--border); padding: 16px 10px;
}
.dev-side a {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: var(--radius-md);
  font-size: 13px; color: var(--text-secondary); margin-bottom: 2px;
}
.dev-side a:hover { background: var(--bg-hover); color: var(--text); }
.dev-side a.active { background: #e6fcf5; color: #087f5b; font-weight: 600; }
.dev-main { flex: 1; padding: 24px; overflow: auto; }
.topbar-modules a.nav-dev.active { color: #087f5b; box-shadow: inset 0 -2px 0 #087f5b; }
.dev-editor-page { height: calc(100vh - var(--topnav-h) - 57px - 44px); }
.dev-editor-page.with-sync { height: calc(100vh - var(--topnav-h) - 57px - 44px - 45px); }

/* === Toast === */
.proto-toast {
  position: fixed; bottom: 48px; left: 50%; transform: translateX(-50%) translateY(80px);
  background: #212529; color: #fff; padding: 10px 20px; border-radius: 8px;
  font-size: 13px; z-index: 200; opacity: 0; transition: all 0.25s;
  box-shadow: var(--shadow-lg); pointer-events: none;
}
.proto-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* === 资源选择页 === */
.picker-page { max-width: 960px; margin: 0 auto; padding: 24px; }
.picker-head { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; }
.picker-card { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }

/* === 流程地图 === */
.flow-map { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
.flow-step {
  padding: 14px; border: 1px solid var(--border); border-radius: var(--radius-md);
  background: var(--bg-white); font-size: 13px;
}
.flow-step strong { display: block; margin-bottom: 6px; color: var(--primary); }
.flow-step span { color: var(--text-muted); font-size: 12px; line-height: 1.5; }
.flow-step a { color: var(--primary); font-size: 12px; margin-top: 8px; display: inline-block; }

/* === 运营档案网格 === */
.ops-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 20px 24px; }
.ops-card {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 16px;
}
.ops-card h4 { font-size: 14px; margin-bottom: 12px; }
.ops-kv { display: flex; justify-content: space-between; font-size: 13px; padding: 6px 0; border-bottom: 1px dashed var(--border); }
.ops-kv:last-child { border-bottom: none; }
.ops-kv .k { color: var(--text-muted); }

