/**
 * 原型共享：URL 参数、顶栏跳转、Toast、创建后回跳
 * agentId 默认 agt_demo_001；name 默认 客服助手
 */
(function (global) {
  var DEFAULT_AGENT = { id: 'agt_demo_001', name: '客服助手', type: 'qa' };

  function params() {
    return new URLSearchParams(window.location.search);
  }

  function agentId() {
    return params().get('id') || params().get('agentId') || DEFAULT_AGENT.id;
  }

  function agentName() {
    return params().get('name') ? decodeURIComponent(params.get('name')) : DEFAULT_AGENT.name;
  }

  function agentType() {
    return params().get('type') || DEFAULT_AGENT.type;
  }

  function qs(extra) {
    var q = new URLSearchParams({ id: agentId(), name: agentName(), type: agentType() });
    if (extra) {
      Object.keys(extra).forEach(function (k) {
        if (extra[k] != null) q.set(k, extra[k]);
      });
    }
    return '?' + q.toString();
  }

  function href(page, extra) {
    return page + qs(extra);
  }

  function toast(msg, ms) {
    var el = document.getElementById('protoToast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'protoToast';
      el.className = 'proto-toast';
      document.body.appendChild(el);
    }
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(el._t);
    el._t = setTimeout(function () { el.classList.remove('show'); }, ms || 2400);
  }

  function initTopbar(ctx) {
    ctx = ctx || 'ops';
    var devLink = document.querySelector('[data-nav-dev]');
    var opsLink = document.querySelector('[data-nav-ops]');
    if (devLink) devLink.href = '06-dev-platform.html' + qs();
    if (opsLink) opsLink.href = 'index.html';

    document.querySelectorAll('.topbar-modules a, .topbar-modules span').forEach(function (el) {
      el.classList.remove('active');
    });
    if (ctx === 'dev') {
      if (devLink) devLink.classList.add('active');
    } else if (opsLink) {
      opsLink.classList.add('active');
    }
  }

  function applyAgentHeader() {
    var name = agentName();
    document.querySelectorAll('[data-agent-name]').forEach(function (el) {
      el.textContent = name;
    });
    document.querySelectorAll('[data-agent-id]').forEach(function (el) {
      el.textContent = agentId();
    });
    document.title = document.title.replace(/客服助手/, name);
  }

  function bindTabs(containerSel) {
    var root = document.querySelector(containerSel);
    if (!root) return;
    root.querySelectorAll('[data-tab]').forEach(function (btn) {
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        var tab = btn.getAttribute('data-tab');
        root.querySelectorAll('[data-tab]').forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        document.querySelectorAll('.agent-tab-panel').forEach(function (p) {
          p.classList.toggle('active', p.id === 'tab-' + tab);
        });
        if (history.replaceState) {
          var u = new URL(window.location.href);
          u.searchParams.set('tab', tab);
          history.replaceState(null, '', u);
        }
      });
    });
    var initial = params().get('tab');
    if (initial) {
      var t = root.querySelector('[data-tab="' + initial + '"]');
      if (t) t.click();
    }
  }

  global.Proto = {
    params: params,
    agentId: agentId,
    agentName: agentName,
    agentType: agentType,
    qs: qs,
    href: href,
    toast: toast,
    initTopbar: initTopbar,
    applyAgentHeader: applyAgentHeader,
    bindTabs: bindTabs,
    DEFAULT_AGENT: DEFAULT_AGENT
  };
})(window);

/**
 * 三列配置编辑器（运营镜像 / 开发平台共用）
 */
(function (global) {
  function pickHref(type) {
    return Proto.href('07-pick-resource.html', { pick: type, return: '05-agent-detail.html' });
  }

  function resManageHref(type) {
    var map = { knowledge: 'knowledge', tool: 'tools', tools: 'tools' };
    return '06-dev-resources.html?res=' + (map[type] || type) + '&' + Proto.qs().slice(1);
  }

  function resourceSection(type, title, count, rows, extraBtn) {
    var pick = pickHref(type);
    var manage = resManageHref(type);
    var thead = rows[0] ? Object.keys(rows[0]).map(function () { return ''; }) : [];
    var headHtml = type === 'knowledge'
      ? '<tr><th style="width:32px;"></th><th>知识库</th><th>规模</th><th>状态</th></tr>'
      : '<tr><th style="width:32px;"></th><th>工具</th><th>标识</th><th>类型</th></tr>';
    var bodyHtml = rows.map(function (r) {
      return '<tr><td><input type="checkbox" ' + (r.checked ? 'checked' : '') + '></td>' +
        '<td>' + r.name + '</td><td>' + r.meta + '</td><td>' + (r.status || '可用') + '</td></tr>';
    }).join('');

    return (
      '<div class="acc-panel' + (extraBtn ? '' : ' collapsed') + '">' +
      '<div class="acc-head" onclick="EditorShell.toggleAcc(this)">' +
      '<span class="acc-arrow">▼</span>' + title +
      '<span style="margin-left:auto;font-size:12px;color:var(--text-muted);font-weight:normal;">已关联 ' + count + ' 个</span></div>' +
      '<div class="acc-body">' +
      '<div class="res-toolbar">' +
      '<input class="input" placeholder="搜索' + title + '…">' +
      '<a href="' + pick + '" class="btn btn-sm btn-primary">+ 添加</a>' +
      '<a href="' + manage + '" class="btn btn-sm">管理资源库 ↗</a>' +
      '</div>' +
      '<table class="res-mini-table">' + headHtml + bodyHtml + '</table>' +
      (extraBtn || '') +
      '</div></div>'
    );
  }

  var HTML = function (mode) {
    var isDev = mode === 'dev';
    return (
      '<div class="dev-col"><div class="dev-col-header">智能体画像 <span style="margin-left:auto;font-size:12px;color:var(--text-muted);">✨ 优化</span></div>' +
      '<div class="dev-col-body"><textarea class="textarea" style="min-height:280px;font-size:13px;line-height:1.6;">企业产品咨询客服助手，专注于解答产品使用问题、处理售后咨询、创建工单。语气友好专业，无法回答时引导转人工。</textarea></div></div>' +

      '<div class="dev-col"><div class="dev-col-header">智能体核心配置</div><div class="dev-col-body"><div class="accordion">' +

      '<div class="acc-panel"><div class="acc-head" onclick="EditorShell.toggleAcc(this)"><span class="acc-arrow">▼</span>模型配置</div>' +
      '<div class="acc-body">' +
      '<div class="res-toolbar"><span style="font-size:13px;font-weight:500;">模型</span>' +
      '<a href="' + resManageHref('models') + '" class="res-link" style="margin-left:auto;">更换模型 ↗</a></div>' +
      '<table class="res-mini-table"><tr><th style="width:32px;"></th><th>模型</th><th>提供商</th><th>上下文</th></tr>' +
      '<tr><td><input type="radio" name="model" checked></td><td>GPT-4o</td><td>OpenAI</td><td>128K</td></tr></table>' +
      '<div style="margin-top:14px;"><div style="font-size:13px;font-weight:500;margin-bottom:6px;">生成多样性</div>' +
      '<div class="segmented"><button class="active">精确</button><button>平衡</button><button>创意</button><button>自定义</button></div></div>' +
      '<div class="slider-row"><span class="lbl">随机性</span><input type="range" value="30"><input class="num-input" value="0.3"></div>' +
      '</div></div>' +

      resourceSection('knowledge', '知识库', 2, [
        { name: '📄 产品使用手册', meta: '120 篇', checked: true, status: '已向量化' },
        { name: '❓ 常见问题 FAQ', meta: '56 条', checked: true, status: '已向量化' },
        { name: '📋 售后服务政策', meta: '8 篇', checked: false, status: '处理中' }
      ]) +

      resourceSection('tool', '工具', 2, [
        { name: '🔍 产品搜索', meta: 'product_search', checked: true, status: 'HTTP' },
        { name: '📝 工单创建', meta: 'create_ticket', checked: true, status: 'HTTP' },
        { name: '📧 邮件发送', meta: 'send_email', checked: false, status: 'MCP' }
      ],
      '<div style="margin-top:10px;font-size:12px;color:var(--text-muted);">未找到工具？<a href="' + resManageHref('tools') + '" class="res-link">在资源库注册 ↗</a></div>') +

      '<div class="acc-panel collapsed"><div class="acc-head" onclick="EditorShell.toggleAcc(this)"><span class="acc-arrow">▼</span>输入/输出 · 变量</div>' +
      '<div class="acc-body"><div class="empty-state" style="padding:24px;"><div>暂无变量</div>' +
      '<button class="btn btn-sm" style="margin-top:8px;" onclick="Proto.toast(\'添加变量\')">+ 添加变量</button></div></div></div>' +

      (!isDev ? '' : '<div class="acc-panel collapsed"><div class="acc-head" onclick="EditorShell.toggleAcc(this)"><span class="acc-arrow">▼</span>工作流</div>' +
      '<div class="acc-body"><a href="' + resManageHref('workflow') + '" class="res-link">关联工作流 ↗</a></div></div>') +

      '</div></div></div>' +

      '<div class="dev-col"><div class="dev-col-header">预览与调试</div>' +
      '<div class="dev-col-body" style="display:flex;flex-direction:column;padding:0;height:100%;">' +
      '<div style="flex:1;padding:16px;overflow-y:auto;text-align:center;color:var(--text-muted);padding-top:48px;">' +
      '<div style="font-size:40px;margin-bottom:8px;">💬</div><div style="font-size:13px;">发送消息开始调试</div></div>' +
      '<div style="padding:12px;border-top:1px solid var(--border);">' +
      '<textarea class="textarea" placeholder="开始对话吧" style="min-height:56px;"></textarea>' +
      '<div style="font-size:11px;color:var(--text-muted);text-align:center;margin-top:6px;">由开发平台运行引擎执行</div></div></div></div>'
    );
  };

  global.EditorShell = {
    mount: function (sel, opts) {
      opts = opts || {};
      var el = document.querySelector(sel);
      if (!el) return;
      el.className = 'dev-editor dev-editor-page with-sync';
      el.innerHTML = HTML(opts.mode || 'ops');
    },
    toggleAcc: function (head) {
      head.parentElement.classList.toggle('collapsed');
    }
  };
})(window);

