/**
 * 三列配置编辑器（与智能体开发平台布局一致）
 */
(function (global) {
  function devManageUrl(res) {
    return '06-dev-resources.html?res=' + res + '&' + Proto.qs().slice(1);
  }

  function devEditorUrl() {
    return Proto.href('06-dev-editor.html');
  }

  /** 运营侧：仅展示已关联资源，新增/管理一律跳转开发平台 */
  function resourceBlock(title, count, rows, resKey, col2, col3) {
    var manage = devManageUrl(resKey);
    var body = rows.map(function (r) {
      return '<tr><td><input type="checkbox" ' + (r.checked ? 'checked' : '') + ' disabled></td>' +
        '<td>' + r.name + '</td><td>' + r.meta + '</td><td>' + (r.status || '可用') + '</td></tr>';
    }).join('');
    return (
      '<div class="acc-panel collapsed">' +
      '<div class="acc-head" onclick="EditorShell.toggleAcc(this)">' +
      '<span class="acc-arrow">▼</span>' + title +
      '<span style="margin-left:auto;font-size:12px;color:var(--text-muted);font-weight:normal;">已关联 ' + count + ' 个</span></div>' +
      '<div class="acc-body">' +
      '<div class="res-toolbar">' +
      '<a href="' + manage + '" class="btn btn-sm btn-primary">添加或管理</a>' +
      '<span style="font-size:12px;color:var(--text-muted);margin-left:8px;">在智能体开发平台中维护</span>' +
      '</div>' +
      '<table class="res-mini-table"><tr><th style="width:32px;"></th><th>' + title + '</th><th>' + col2 + '</th><th>' + col3 + '</th></tr>' + body + '</table>' +
      '</div></div>'
    );
  }

  var HTML = function () {
    return (
      '<div class="dev-col">' +
