function runSyncPipeline() {
  showState('syncing');
  var steps = [4, 5, 6, 7, 8];
  var i = 0;
  function setStep(n, state) {
    document.querySelectorAll('.sync-step').forEach(function(el) {
      var s = parseInt(el.getAttribute('data-step'), 10);
      el.classList.remove('active', 'done', 'fail');
      if (s < n) el.classList.add('done');
      else if (s === n) el.classList.add(state || 'active');
    });
  }
  setStep(4, 'active');
  function next() {
    if (i >= steps.length) {
      var url = configPageUrl();
      var id = new URL(url, location.href).searchParams.get('id');
      var name = document.getElementById('agentName').value.trim();
      Proto.onAgentCreated(id, name, selectedType, selectedScope);
      showState('success');
      startCountdown();
      return;
    }
    var step = steps[i];
    setStep(step, 'active');
    setTimeout(function() {
      if ((step === 5 || step === 6) && !createSucceeded()) {
        setStep(step, 'fail');
        document.getElementById('failDetail').textContent =
          step === 5 ? '通知开发平台失败，请检查网络后重试' : '开发平台创建实例失败，运营草稿已保留';
        showState('failure');
        return;
      }
      setStep(step, 'done');
      i++;
      if (i < steps.length) setStep(steps[i], 'active');
      next();
    }, step === 4 ? 400 : 500);
  }
  next();
}

