function runSyncPipeline() {
  showState('syncing');
  var msgs = [
    { main: '正在保存基本信息…', sub: '请稍候' },
    { main: '正在完成创建…', sub: '即将进入配置页' }
  ];
  var phase = 0;
  function runPhase() {
    if (phase >= msgs.length) {
      var url = configPageUrl();
      var id = new URL(url, location.href).searchParams.get('id');
      var name = document.getElementById('agentName').value.trim();
      if (typeof Proto !== 'undefined') Proto.onAgentCreated(id, name, selectedType, selectedScope);
      showState('success');
      startCountdown();
      return;
    }
    document.getElementById('syncMainText').textContent = msgs[phase].main;
    document.getElementById('syncSubText').textContent = msgs[phase].sub;
    setTimeout(function () {
      if (phase === 1 && !createSucceeded()) {
        document.getElementById('failDetail').textContent = '创建未完成，请检查网络后重试';
        showState('failure');
        return;
      }
      phase++;
      runPhase();
    }, phase === 0 ? 700 : 900);
  }
  runPhase();
}

