(function (global) {
  function devManageUrl(res, q) {
    q = q || (global.Proto ? Proto.qs().slice(1) : '');
    return '06-dev-resources.html?res=' + res + (q ? '&' + q : '');
  }

  function devEditorUrl(q) {
    return global.Proto ? Proto.href('06-dev-editor.html') : '06-dev-editor.html';
  }

