      '</div></div>'
    );
  }

  function buildTestColumn() {
    return (
      '<div class="dev-col">' +
      '<div class="dev-col-header">预览与测试</div>' +
      '<div class="dev-col-body" style="display:flex;flex-direction:column;padding:0;min-height:360px;">' +
      '<div id="debugMsgs" style="flex:1;padding:16px;overflow-y:auto;">' +
      '<div style="text-align:center;color:var(--text-muted);padding-top:48px;">' +
      '<div style="font-size:36px;margin-bottom:8px;">💬</div>' +
      '<div style="font-size:13px;">输入消息进行测试</div></div></div>' +
      '<div style="padding:12px;border-top:1px solid var(--border);">' +
