  function buildHTML(q) {
    return buildPromptColumn() + buildMiddleColumn(q) + buildTestColumn();
  }

  function wireDevLinks(root, q) {
    q = q || (global.Proto ? Proto.qs().slice(1) : '');
    var scope = root || document;
