.dev-editor-page.with-sync { height: calc(100vh - var(--topnav-h) - 57px - 44px - 45px); }

/* === 智能体核心配置（对齐开发平台） === */
.dev-col-core { min-width: 0; }
.core-config-scroll { padding: 12px !important; overflow-y: auto; }
.core-config { display: flex; flex-direction: column; gap: 10px; }
.core-section {
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-md); overflow: hidden;
}
.core-section-head {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 14px; cursor: pointer; user-select: none;
  font-size: 14px; font-weight: 600; color: var(--text);
  background: #fafbfc;
}
.core-section-head:hover { background: var(--bg-hover); }
.core-chevron { font-size: 10px; color: var(--text-muted); transition: transform .2s; }
.core-section.collapsed .core-chevron { transform: rotate(-90deg); }
.core-section.collapsed .core-section-body { display: none; }
.core-section-body { padding: 12px 14px 14px; }
.core-field { margin-bottom: 14px; }
.core-field > label {
  display: block; font-size: 13px; color: var(--text-secondary);
  margin-bottom: 8px;
}
.core-select-wrap {
  display: flex; align-items: center; gap: 8px;
}
.core-select { flex: 1; padding: 8px 10px; font-size: 13px; }
.core-seg { margin-top: 0; }
.core-seg button { font-size: 12px; padding: 6px 8px; }
.core-slider {
  display: grid; grid-template-columns: 100px 1fr 72px;
  align-items: center; gap: 10px;
}
.core-slider > label { margin: 0; }
.core-subhead {
  font-size: 13px; font-weight: 600; color: var(--text);
  margin: 16px 0 10px; padding-top: 12px;
  border-top: 1px dashed var(--border);
}
.core-row-link {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 0; font-size: 13px; color: var(--text);
  border-bottom: 1px solid var(--border);
}
.core-row-link:last-child { border-bottom: none; }
.core-row-actions { display: flex; align-items: center; gap: 6px; }
.core-jump {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: var(--radius-sm);
  color: var(--text-muted); border: 1px solid var(--border);
  background: var(--bg-white); text-decoration: none;
}
.core-jump:hover { color: var(--primary); border-color: var(--primary); background: var(--primary-light); }
.core-icon-btn {
  width: 28px; height: 28px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-white);
  color: var(--text-muted); font-size: 16px; line-height: 1; cursor: pointer;
}
.core-icon-btn:hover { color: var(--primary); border-color: var(--primary); }
.core-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.core-tag {
  font-size: 12px; padding: 4px 10px; border-radius: 12px;
  background: var(--bg-page); border: 1px solid var(--border); color: var(--text-secondary);
}
.switch-sm { transform: scale(0.85); transform-origin: right center; }

/* === 审核进度条 === */
.audit-progress-page { max-width: 880px; margin: 0 auto; padding: 24px; }
.audit-stepper {
  display: flex; align-items: flex-start; justify-content: space-between;
  margin: 32px 0 28px; position: relative;
}
.audit-stepper::before {
  content: ""; position: absolute; top: 18px; left: 8%; right: 8%;
  height: 2px; background: var(--border); z-index: 0;
}
.audit-step {
  flex: 1; text-align: center; position: relative; z-index: 1;
  padding: 0 8px;
}
.audit-step .dot {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--bg-white); border: 2px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 10px; font-size: 14px; color: var(--text-muted);
}
.audit-step.done .dot { background: var(--success); border-color: var(--success); color: #fff; }
.audit-step.current .dot { background: var(--primary); border-color: var(--primary); color: #fff; box-shadow: 0 0 0 4px var(--primary-light); }
.audit-step .label { font-size: 13px; font-weight: 600; color: var(--text); }
.audit-step .sub { font-size: 11px; color: var(--text-muted); margin-top: 4px; line-height: 1.4; }
.audit-step.done .label { color: var(--success); }
.audit-step.current .label { color: var(--primary); }
.audit-next-card {
  background: linear-gradient(135deg, #e7f5ff 0%, #f8f9fa 100%);
  border: 1px solid #b6d4fe; border-radius: var(--radius-lg);
  padding: 20px 24px; margin-bottom: 24px;
}
.audit-next-card h3 { font-size: 15px; margin: 0 0 8px; }
.audit-next-card p { font-size: 13px; color: var(--text-secondary); margin: 0; line-height: 1.6; }
.audit-next-card .approver {
  display: flex; align-items: center; gap: 12px; margin-top: 14px;
}
.audit-next-card .approver .av {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--primary); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; font-weight: 600;
}
.audit-banner {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 12px 24px; background: #fff9db; border-bottom: 1px solid #ffe066;
  font-size: 13px;
}
.audit-banner a { color: var(--primary); font-weight: 500; margin-left: auto; }

