function refreshStateUi() {
  var st = Proto.getState();
  Proto.applyStatusTags();
  document.getElementById('opsCalls').textContent = st.calls7d || 0;
  document.getElementById('kpiCalls').textContent = st.calls7d || 0;
  document.getElementById('opsDebug').textContent = st.debugOk ? '已测试' : '未测试';
  var chat = document.getElementById('userChatLink');
  if (st.status === 'published') {
    chat.style.display = 'inline-flex';
    chat.href = Proto.href('09-user-chat.html');
  } else {
    chat.style.display = 'none';
  }
  if (st.status === 'offline') {
    document.getElementById('releaseDesc').textContent = '该智能体已下架。如需重新对外使用，请点击右上角「发布」。';
  }
  var banner = document.getElementById('auditBanner');
  var auditLink = document.getElementById('auditProgressLink');
  if (st.status === 'review') {
    banner.classList.remove('hidden');
    auditLink.href = Proto.href('08-audit-status.html');
    document.getElementById('opsShelf').textContent = '审核中';
  } else {
    banner.classList.add('hidden');
  }
}

